   168  void IPv4Layer::initLayer()
   169  {
   170          const size_t headerLen = sizeof(iphdr);
   171          m_DataLen = headerLen;
   172          m_Data = new uint8_t[headerLen];
   173          m_Protocol = IPv4;
   174          memset(m_Data, 0, headerLen);
   175          iphdr* ipHdr = getIPv4Header();
   176          ipHdr->internetHeaderLength = (5 & 0xf);
   177          m_NumOfTrailingBytes = 0;
   178          m_TempHeaderExtension = 0;
   179  }
