   181  void IPv4Layer::initLayerInPacket(bool setTotalLenAsDataLen)
   182  {
   183          m_Protocol = IPv4;
   184          m_NumOfTrailingBytes = 0;
   185          m_TempHeaderExtension = 0;
   186          if (setTotalLenAsDataLen)
   187          {
   188                  size_t totalLen = be16toh(getIPv4Header()->totalLength);
   189                  // if totalLen == 0 this usually means TCP Segmentation Offload (TSO). In this case we should ignore the value of totalLen
   190                  // and look at the data captured on the wire
   191                  if ((totalLen < m_DataLen) && (totalLen !=0))
   192                          m_DataLen = totalLen;
   193          }
   194  }
